        });
        if (response.data.success) {
          ElMessage.success('成员添加成功');

          // 1. 重新加载群成员信息
          await loadGroupMembers();

          // 2. 重新加载可添加的用户列表
          await loadAllUsers();

          // 获取添加的用户名列表
          const addedUserNames = allUsers.value.filter(user => selectedUserIds.value.has(user.id)).map(user => user.username).join('、');

          // 发送系统消息：用户邀请成员加入群聊
          await sendSystemMessage(props.groupInfo.group_id, `${store.state.user.username} 邀请 ${addedUserNames} 加入群聊`, 'add_members');

          // 4. 关闭添加成员弹窗
          closeAddMemberDialog();

          // 5. 通知父组件更新
          emit('group-updated');

          // 6. 立即返回聊天界面
          emit('update:visible', false);

          // 7. 触发聊天界面刷新
          store.commit('chat/SET_CURRENT_CHAT_ID', props.groupInfo.group_id);
        }
      } catch (error) {
        console.error('添加成员失败:', error);
        ElMessage.error('添加成员失败');
      }
    };
    watch(() => props.visible, async newVisible => {
      if (newVisible && props.groupInfo.group_id) {
        await loadGroupMembers();
        try {
          const response = await axios.get(`${API_CONFIG.BASE_URL}/group/${props.groupInfo.group_id}/mute-status?user_id=${currentUserId.value}`, {
            headers: {
              Authorization: `Bearer ${store.state.token}`
            }
          });
          if (response.data.success) {
            isMuted.value = response.data.muted;
          }
        } catch (error) {
          console.error('获取免打扰状态失败:', error);
        }
      }
    });

    // 监听路由变化
    watch(() => route.params.id, newId => {
      if (newId) {
        checkGroupValidity();
      }
    });
    onMounted(async () => {
      if (props.visible && props.groupInfo.group_id) {
        await loadGroupMembers();
        checkGroupValidity();
        try {
          const response = await axios.get(`${API_CONFIG.BASE_URL}/group/${props.groupInfo.group_id}/mute-status?user_id=${currentUserId.value}`, {
            headers: {
              Authorization: `Bearer ${store.state.token}`
            }
          });
          if (response.data.success) {
            isMuted.value = response.data.muted;
          }
        } catch (error) {
          console.error('获取免打扰状态失败:', error);
        }
      }
    });
    return {
      currentUserId,
      groupMembers,
      validGroupMembers,
      currentUser,
      isMuted,
      showEditName,
      handleAvatarError,
      editGroupName,
      showAddMember,
      searchKeyword,
      filteredUsers,
      isGroupOwner,
      handleUserListScroll,
      userListRef,
      dismissGroup,
      groupAvatarUrls,
      getFullUrl,
      selectedCount,
      pagination,
      hoverMemberId,
      handleSearchInput,
      isUserInGroup,
      getAvatarPosition,
      getMemberAvatar,
      getMemberRole,
      getMemberName,
      getMemberId,
      getMemberKey,
      canRemoveMember,
      close,
      showEditNameDialog,
      cancelEditName,
      confirmEditName,
      toggleMute,
      removeMember,
      exitGroup,
      showAddMemberDialog,
      closeAddMemberDialog,
      selectUser,
      isUserSelected,
      confirmAddMembers
    };
  }
};
